wireframing_ui <- function(id) { ns <- NS(id); tagList(
  lab_section(c("Build a simple page hierarchy.", "Compare component choices.", "Explain how layout supports a task."),
    tagList(p("Challenge · Sketch a landing page that helps a new student find a course."), fluidRow(column(4, selectInput(ns("component"), "Component", c("Page heading", "Navigation", "Body text", "Image placeholder", "Primary button", "Form field", "Content section")), actionButton(ns("add"), "Add to canvas", class="btn-primary w-100"), hr(), selectInput(ns("screen"), "Canvas width", c("Desktop · 1440 px"="desktop", "Tablet · 768 px"="tablet", "Mobile · 390 px"="mobile")), actionButton(ns("clear"), "Clear canvas", class="btn-outline-secondary w-100"), br(), br(), downloadButton(ns("export"), "Export sketch")), column(8, uiOutput(ns("canvas"))))),
    "Which element establishes the clearest next step? What would you change for a narrow screen?")) }
wireframing_server <- function(id) { moduleServer(id, function(input, output, session) {
  items <- reactiveVal(character()); observeEvent(input$add, items(c(items(), input$component))); observeEvent(input$clear, items(character()))
  output$canvas <- renderUI({ style <- switch(input$screen %||% "desktop", desktop="max-width:100%", tablet="max-width:560px", mobile="max-width:310px;margin:auto"); div(class="wire-canvas", style=paste0("width:100%;",style), if(length(items())==0) p(class="muted", "Your canvas is empty. Add a component to begin.") else lapply(seq_along(items()), function(i) div(class="wire-item d-flex justify-content-between align-items-center", tags$span(paste0(i,". ",items()[i])), actionButton(session$ns(paste0("remove",i)), "Remove", class="btn-sm btn-outline-secondary", onclick=paste0("Shiny.setInputValue('",session$ns("remove_index"),"',",i,",{priority:'event'})"))))) })
  observeEvent(input$remove_index, { x<-items(); if(input$remove_index<=length(x)) items(x[-input$remove_index]) })
  output$export <- downloadHandler(filename=function() "ixd-wireframe.txt", content=function(file) writeLines(c("IxD Lab · Wireframing sketch", paste0("Canvas: ",input$screen), "", if(length(items())) paste(seq_along(items()),items(),sep=". ") else "(empty)"),file))
}) }
